(async () => {
  const inputPath = process.env.INPUT_PATH;
  const outputPath = process.env.OUTPUT_PATH;
  if (!inputPath) throw new Error('Missing INPUT_PATH');
  if (!outputPath) throw new Error('Missing OUTPUT_PATH');
  globalThis.inputPath = inputPath;
  globalThis.outputPath = outputPath;
})();

(async () => {
  const { parseFile } = await import('fast-csv');
  const { writeFileSync } = await import('node:fs');
  const rows = [];
  await new Promise((resolve, reject) => {
    parseFile(globalThis.inputPath, { headers: false })
      .on('error', err => reject(err))
      .on('data', row => rows.push(row))
      .on('end', () => resolve());
  });
  if (rows.length === 0) {
    writeFileSync(globalThis.outputPath, '');
    globalThis.markdownPath = globalThis.outputPath;
    return;
  }
  const header = rows[0];
  const lines = [];
  lines.push(`| ${header.join(' | ')} |`);
  lines.push(`| ${header.map(() => '---').join(' | ')} |`);
  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    lines.push(`| ${row.join(' | ')} |`);
  }
  const markdown = lines.join('\n');
  writeFileSync(globalThis.outputPath, markdown);
  globalThis.markdownPath = globalThis.outputPath;
})();
